CREATE DATABASE IF NOT EXISTS template_rest CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE template_rest;
CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL) ENGINE=InnoDB;
CREATE TABLE products(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,price_cents INT UNSIGNED NOT NULL,active BOOL DEFAULT TRUE,FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE delivery_zones(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL,fee_cents INT UNSIGNED NOT NULL,min_order_cents INT UNSIGNED NOT NULL DEFAULT 0,active BOOL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(150) NOT NULL,customer_phone VARCHAR(24) NOT NULL,fulfillment ENUM('pickup','delivery') NOT NULL,address VARCHAR(500),zone_id INT UNSIGNED,subtotal_cents INT UNSIGNED NOT NULL,delivery_fee_cents INT UNSIGNED NOT NULL,total_cents INT UNSIGNED NOT NULL,status ENUM('pending','accepted','preparing','ready','dispatched','completed','cancelled') DEFAULT 'pending',payment_status ENUM('pending','paid','failed','refunded') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(zone_id) REFERENCES delivery_zones(id)) ENGINE=InnoDB;
CREATE TABLE order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price_cents INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB;
CREATE TABLE reservation_slots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,date DATE NOT NULL,time TIME NOT NULL,capacity INT UNSIGNED NOT NULL,enabled BOOL DEFAULT TRUE,UNIQUE KEY uniq_slot(date,time)) ENGINE=InnoDB;
CREATE TABLE reservations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slot_id BIGINT UNSIGNED NOT NULL,customer_name VARCHAR(150) NOT NULL,customer_phone VARCHAR(24) NOT NULL,guests INT UNSIGNED NOT NULL,status ENUM('pending','confirmed','cancelled','completed') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(slot_id) REFERENCES reservation_slots(id)) ENGINE=InnoDB;
CREATE TABLE admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL);
CREATE TABLE payment_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(50) NOT NULL,external_id VARCHAR(190) NOT NULL,order_id BIGINT UNSIGNED,UNIQUE KEY uniq_event(provider,external_id),FOREIGN KEY(order_id) REFERENCES orders(id));
